from rest_framework import serializers, viewsets, permissions
from .models import DigitalAsset, AssetCategory

class DigitalAssetSerializer(serializers.HyperlinkedModelSerializer):
    category = serializers.HyperlinkedRelatedField(
        view_name='assetcategory-detail',
        queryset=AssetCategory.objects.none()
    )

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        request = self.context.get('request')
        if request and hasattr(request, 'user'):
            self.fields['category'].queryset = AssetCategory.objects.filter(
                organization=request.user.organization
            )

    class Meta:
        model = DigitalAsset
        fields = ('url', 'id', 'title', 'file_url', 'category')

class DigitalAssetViewSet(viewsets.ModelViewSet):
    serializer_class = DigitalAssetSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return DigitalAsset.objects.filter(organization=self.request.user.organization)
